 if(t.h<=0){kill(other,i,a);if(a.growth&&a.h>0){a.a++;logBattle(`${a.n}击杀成长，攻击升至${a.a}`)}else if(a.x==='soul'&&a.h>0)a.a=Math.max(a.a,Math.min(3,a.a+1))}
